/**
 * @description Integration Hub Lite public API: publish outbound events, the interfaces for payload, inbound,
 * response handler and connection auth classes, and the transaction trigger entry point.
 * @group Integration Hub
 */
public with sharing class IntegrationHub {

    /** @description Outbound transaction waiting to be sent. */
    public static final String STATUS_PENDING = 'Pending';
    /** @description Inbound call received. */
    public static final String STATUS_RECEIVED = 'Received';
    /** @description Sent; waiting for the callback. */
    public static final String STATUS_SENT = 'Sent';
    /** @description Finished successfully. */
    public static final String STATUS_SUCCESS = 'Success';
    /** @description Failed. With Next Retry At set it waits for auto-retry; otherwise it is retried by hand. */
    public static final String STATUS_FAILED = 'Failed';
    /** @description Set by a manual retry; the transaction trigger sends it at once. */
    public static final String STATUS_RETRY = 'Retry';
    /** @description From earlier releases; no longer set. Retry still accepts it. */
    public static final String STATUS_ABANDONED = 'Abandoned';
    /** @description Salesforce calls the system. */
    public static final String OUTBOUND = 'Outbound';
    /** @description The system calls Salesforce. */
    public static final String INBOUND = 'Inbound';
    /** @description Connection Type: Salesforce logs in through the Named Credential (also when the type is blank). */
    public static final String CONNECTION_NAMED_CREDENTIAL = 'Named Credential';
    /** @description Connection Type: the connection's Auth Class adds the login header at send time. */
    public static final String CONNECTION_APEX_AUTH = 'Apex Auth';

    /**
     * @description Configuration or handler error.
     */
    public class HubException extends Exception {}

    /**
     * @description Implemented by the class an inbound event names in Handler Class.
     */
    public interface IInboundHandler {
        /**
         * @description Processes one inbound call.
         * @param ctx the call
         * @return the result: IntegrationHub.inboundSuccess(...) or IntegrationHub.inboundFailure(...)
         */
        InboundResult handle(InboundContext ctx);
    }

    /**
     * @description Implemented by the class an outbound event names in Response Handler Class. It runs after the
     * immediate reply and after the callback; it may change fields of ctx.txn, which are saved afterwards. With
     * Business Data In Response it runs in a background job, may run more than once on the same data (rerun, repeated
     * callback) and should therefore update or upsert, never insert blindly.
     */
    public interface IResponseHandler {
        /**
         * @description Processes a reply or a callback.
         * @param ctx the reply
         */
        void handle(ResponseContext ctx);
    }

    /**
     * @description Implemented by the class an outbound event names in Payload Class (Payload Source = Apex Class).
     * It is called once per send with all the records and returns the body of each record.
     */
    public interface IPayloadBuilder {
        /**
         * @description Builds the bodies of one send.
         * @param request the event and the record Ids
         * @return the body per record Id: a Map (the transaction Id key is added to it) or a JSON String (sent as is)
         */
        Map<Id, Object> build(PayloadRequest request);
    }

    /**
     * @description Implemented by the class an Apex Auth connection names in Auth Class, for a custom token login that a
     * Named Credential cannot do. It is called after the request is built and before it is sent: log in (through this
     * or another Named Credential, never with a secret stored in a field), then set the header on ctx.request, e.g.
     * Authorization: Bearer token. Keep the token with IntegrationHubTokenCache. A CalloutException (the token URL
     * is down or timed out) fails the send as temporary, so auto-retry applies; any other exception fails it for good
     * (permanent) with your message.
     */
    public interface IConnectionAuth {
        /**
         * @description Adds the login to one request.
         * @param ctx the request, the connection, and refresh = true after a 401 (get a new token)
         */
        void authorize(AuthContext ctx);
    }

    /**
     * @description What a connection auth class gets.
     */
    public class AuthContext {
        /** @description The request about to be sent; set the login header on it. */
        public HttpRequest request;
        /** @description The connection (Id, Name, Named_Credential__c, Connection_Type__c, Auth_Class__c). */
        public IH_Connection__c connection;
        /** @description True after the system answered 401: ignore any cached token and log in again. */
        public Boolean refresh = false;
        /** @description Event key of the send; null for Check connection. */
        public String eventKey;
    }

    /**
     * @description What a payload class gets: the event and every record of the send.
     */
    public class PayloadRequest {
        /** @description Event key. */
        public String eventKey;
        /** @description API name of the records' object. */
        public String relatedObject;
        /** @description Ids of the records to build bodies for. */
        public List<Id> recordIds = new List<Id>();
        /** @description Transaction Id of each record. */
        public Map<Id, Id> transactionIdByRecordId = new Map<Id, Id>();
    }

    /**
     * @description One inbound call, given to the inbound handler.
     */
    public class InboundContext {
        /** @description Event key from the URL. */
        public String eventKey;
        /** @description Raw request body. */
        public String body;
        /** @description Parsed request body. */
        public Map<String, Object> data;
        /** @description Request headers. */
        public Map<String, String> headers;
        /** @description Integration transaction of this call. */
        public Id transactionId;
    }

    /**
     * @description Result of an inbound handler.
     */
    public class InboundResult {
        /** @description True when the call succeeded. */
        public Boolean success = false;
        /** @description HTTP status for a failure (default 422). */
        public Integer statusCode;
        /** @description Error text for a failure. */
        public String message;
        /** @description Record created or updated. */
        public Id recordId;
        /** @description Extra data returned to the caller. */
        public Object data;
    }

    /**
     * @description A reply or callback, given to the response handler.
     */
    public class ResponseContext {
        /** @description The transaction; field changes are saved afterwards. */
        public IH_Transaction__c txn;
        /** @description Id of the transaction. */
        public Id transactionId;
        /** @description The published record. */
        public Id relatedRecordId;
        /** @description HTTP status of the reply (null for a callback). */
        public Integer httpStatus;
        /** @description Reply or callback body. */
        public String body;
        /** @description True for a callback, false for the immediate reply. */
        public Boolean isCallback = false;
        /**
         * @description The "data" object of the reply or callback body, parsed; null when the body has none. Events with
         * Business Data In Response get it in the background job.
         */
        public Map<String, Object> data;
        /**
         * @description A short line the handler may set, e.g. "Case updated, 2 shipments created". Saved to Business
         * Result (first 255 characters) when the handler runs in the background.
         */
        public String result;
    }

    /**
     * @description Publishes an outbound event for records. Null-safe; does nothing when the event is missing,
     * inactive or not outbound, when publishing is disabled, or when there is nothing to send. Never blocks the save.
     * @param eventKey the event key, e.g. CASE_WEB_CREATED
     * @param records the records (may be null)
     * @return the Ids of the transactions created
     */
    public static List<Id> publish(String eventKey, List<SObject> records) {
        List<Id> ids = new List<Id>();
        for (SObject r : records == null ? new List<SObject>() : records) {
            if (r != null && r.Id != null) {
                ids.add(r.Id);
            }
        }
        return createTransactions(eventKey, ids);
    }

    /**
     * @description Publishes an outbound event for record Ids. See publish(String, List<SObject>).
     * @param eventKey the event key
     * @param recordIds the record Ids (may be null)
     * @return the Ids of the transactions created
     */
    public static List<Id> publish(String eventKey, List<Id> recordIds) {
        return createTransactions(eventKey, recordIds);
    }

    /**
     * @description Runs the transaction trigger. IH_TransactionTrigger calls only this.
     */
    public static void handleTrigger() {
        if (Trigger.isAfter && Trigger.isInsert) {
            IntegrationHubSharing.copyShares((List<IH_Transaction__c>) Trigger.new);
        } else if (Trigger.isAfter && Trigger.isUpdate) {
            IntegrationHubSender.onUpdate((List<IH_Transaction__c>) Trigger.new, (Map<Id, IH_Transaction__c>) Trigger.oldMap);
        }
    }

    /**
     * @description Copies the related records' sharing to their transactions again. Call it from your sharing logic
     * when the related records' access changes.
     * @param relatedRecordIds the related record Ids
     */
    public static void syncSharing(Set<Id> relatedRecordIds) {
        IntegrationHubSharing.resync(relatedRecordIds);
    }

    /**
     * @description Successful inbound result.
     * @param recordId the record created or updated (may be null)
     * @param data extra data for the caller (may be null)
     * @return the result
     */
    public static InboundResult inboundSuccess(Id recordId, Object data) {
        InboundResult r = new InboundResult();
        r.success = true;
        r.statusCode = 200;
        r.recordId = recordId;
        r.data = data;
        return r;
    }

    /**
     * @description Failed inbound result.
     * @param statusCode the HTTP status for the caller, e.g. 400 or 422
     * @param message the error text
     * @return the result
     */
    public static InboundResult inboundFailure(Integer statusCode, String message) {
        InboundResult r = new InboundResult();
        r.statusCode = statusCode == null ? 422 : statusCode;
        r.message = message;
        return r;
    }

    /**
     * @description Creates an instance of a class by name.
     * @param className the class name
     * @return the instance
     */
    public static Object createInstance(String className) {
        Type t = String.isBlank(className) ? null : Type.forName(className.trim());
        if (t == null) {
            throw new HubException('Class not found: ' + className);
        }
        return t.newInstance();
    }

    /**
     * @description Shortens a text to a field length.
     * @param value the text
     * @param maxLength the field length
     * @return the text, cut when longer
     */
    public static String clip(String value, Integer maxLength) {
        return value == null || value.length() <= maxLength ? value : value.left(maxLength);
    }

    /**
     * @description Writes an error to a transaction (message and summary).
     * @param t the transaction
     * @param message the error text
     */
    public static void setError(IH_Transaction__c t, String message) {
        t.Error_Message__c = clip(message, 32768);
        t.Error_Summary__c = clip(message, 255);
    }

    private static List<Id> createTransactions(String eventKey, List<Id> recordIds) {
        List<Id> created = new List<Id>();
        Boolean nothing = String.isBlank(eventKey) || recordIds == null || recordIds.isEmpty() || publishingDisabled();
        IH_Event__c ev = nothing ? null : outboundEvent(eventKey);
        if (ev == null) {
            return created;
        }
        List<IH_Transaction__c> txns = new List<IH_Transaction__c>();
        for (Id rid : new Set<Id>(recordIds)) {
            if (rid != null) {
                txns.add(new IH_Transaction__c(Event__c = ev.Id, Event_Name__c = ev.Event_Key__c, Direction__c = OUTBOUND,
                    Status__c = STATUS_PENDING, Related_Record_Id__c = rid, Related_Object__c = String.valueOf(rid.getSObjectType()),
                    Retry_Count__c = 0, Correlation_Id__c = EncodingUtil.convertToHex(Crypto.generateAesKey(128))));
            }
        }
        IntegrationHubData.Outcome outcome = IntegrationHubData.insertEach(txns);
        for (Integer i = 0; i < txns.size(); i++) {
            if (outcome.errorAt(i) == null) {
                created.add(txns[i].Id);
            }
        }
        IntegrationHubSender.enqueue(created);
        return created;
    }

    /**
     * @description True when Disable Publishing is ticked for the running user, its profile or the org
     * (Integration Hub Settings). Publishing and the auto-retry sweep then send nothing.
     * @return whether publishing is disabled
     */
    public static Boolean publishingDisabled() {
        IH_Settings__c settings = IH_Settings__c.getInstance();
        return settings != null && settings.Disable_Publishing__c == true;
    }

    private static IH_Event__c outboundEvent(String eventKey) {
        return (IH_Event__c) IntegrationHubData.queryFirst(
            'SELECT Id, Event_Key__c FROM IH_Event__c WHERE Event_Key__c = :k AND Active__c = true AND Direction__c = :d LIMIT 1',
            new Map<String, Object>{ 'k' => eventKey, 'd' => OUTBOUND });
    }
}
